#include "AutoFit.h"
#include "ReferenceFile.h"
#include <iostream>
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
int main(){try{
 juce::AudioFormatManager formats;formats.registerBasicFormats();auto file=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("nova_reference_test",".wav",false);
 {auto stream=file.createOutputStream();check(bool(stream),"temp stream");juce::WavAudioFormat wav;std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(stream.release(),8000,2,16,{},0));check(bool(writer),"wave writer");juce::AudioBuffer<float> data(2,256000);for(int i=0;i<data.getNumSamples();++i){double hz=i<128000?220:660;data.setSample(0,i,static_cast<float>(.3*std::sin(2*nova::pi*hz*i/8000)));data.setSample(1,i,static_cast<float>(.1*std::sin(2*nova::pi*330*i/8000)));}check(writer->writeFromAudioSampleBuffer(data,0,data.getNumSamples()),"wave write");}
 std::atomic<bool> cancel{false};std::atomic<float> progress{0};auto overview=readReferenceOverview(formats,file,cancel,progress);check(overview&&overview->duration==32&&overview->peaks.size()==1000&&progress.load()==1,"entire long-file overview");check(overview->mips.size()==1&&overview->mips.back().size()==125,"multiresolution overview");float maximum=0;for(const auto& pair:overview->mips.back())maximum=std::max(maximum,pair.high);check(maximum>.299f,"coarse overview preserves peaks");auto selected=readSelectedReference(formats,*overview,{30.125,30.625});check(selected->left.size()==4000&&selected->right.size()==4000,"only selected region decoded");for(int i=0;i<4000;++i){double expected=.3*std::sin(2*nova::pi*660*(241000+i)/8000);check(std::abs(selected->left[i]-expected)<.0001,"exact source frame offset after 30 seconds");}check(selected->tonal&&std::abs(selected->estimatedHz-660)<5,"pitch comes from selected region");auto listen=readSelectedReference(formats,*overview,{30.125,30.625},false);check(!listen->tonal&&listen->left==selected->left&&listen->right==selected->right,"audition decodes exact same selection without pitch analysis");auto last=readSelectedReference(formats,*overview,{31.95,32});check(last->left.size()==400,"selection ending at EOF");cancel.store(true);check(!readReferenceOverview(formats,file,cancel,progress),"waveform load cancellation");cancel.store(false);file.appendText("x");bool rejected=false;try{readSelectedReference(formats,*overview,{1,2});}catch(...){rejected=true;}check(rejected,"changed file rejected");file.deleteFile();
 auto contextFile=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("nova_context_test",".wav",false);
 {auto stream=contextFile.createOutputStream();juce::WavAudioFormat wav;std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(stream.release(),8000,2,16,{},0));check(bool(writer),"context WAV writer");juce::AudioBuffer<float> data(2,8000*65);for(int i=0;i<data.getNumSamples();++i){data.setSample(0,i,static_cast<float>(.3*std::sin(2*nova::pi*220*i/8000)));data.setSample(1,i,static_cast<float>(.2*std::sin(2*nova::pi*330*i/8000)));}check(writer->writeFromAudioSampleBuffer(data,0,data.getNumSamples()),"context WAV write");}
 auto longView=readReferenceOverview(formats,contextFile,cancel,progress);check(longView&&longView->duration==65,"long context source overview");auto context=readSelectedReference(formats,*longView,{2,62},false,60);check(context->left.size()==480000&&context->right.size()==480000,"entire 60s context decoded");for(int i:{0,1,240000,479999})check(std::abs(context->left[i]-.3*std::sin(2*nova::pi*220*(16000+i)/8000))<.0001,"exact context frame at start/middle/end");bool shortRejected=false;try{readSelectedReference(formats,*longView,{2,62},false);}catch(...){shortRejected=true;}check(shortRejected,"short-note reader does not silently accept a long selection");bool capRejected=false;try{readSelectedReference(formats,*longView,{2,63},false,60);}catch(...){capRejected=true;}check(capRejected,"context beyond 60s rejected");contextFile.deleteFile();
 std::cout<<"PASS: full 32s stereo WAV waveform, exact 30.125-30.625s decode/pitch, EOF, cancellation, changed-file detection; explicit 60s context read, exact frames and caps\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
